/**
 * Unity WebGL Entry Point
 * This file provides a simplified entry point for Unity WebGL builds
 * that doesn't depend on the full Balancy WASM module
 */

import { WebViewManager } from './src/WebViewManager';
import { IframeController } from './src/IframeController';
import { MessageBridge } from './src/MessageBridge';
import { CodeInjector } from './src/CodeInjector';
import type { WebViewOptions } from './src/types/WebViewTypes';
import bridgeCode from './resources/balancy-webview-bridge.js?raw';

/**
 * Simplified BalancyWebView for Unity WebGL
 * Does not require Balancy WASM, all data comes from Unity C#
 */
class UnityBalancyWebView {
  private static _instance: UnityBalancyWebView | null = null;
  private webViewManager: WebViewManager;
  private eventHandlers: Map<string, Function[]> = new Map();
  private _ownerJson: string = '';
  private _additionalInfo: string = '';
  private _manifestContent: any = null;
  private _scriptsCode: string = '';
  private activeViewId: string | null = null;
  private closingViewId: string | null = null;
  private _shellId: string | null = null;

  /**
   * Get singleton instance
   */
  static getInstance(): UnityBalancyWebView {
    if (!this._instance) {
      this._instance = new UnityBalancyWebView();
    }
    return this._instance;
  }

  private constructor() {
    // Initialize WebViewManager with Unity-friendly defaults
    this.webViewManager = new WebViewManager({
      transparent: true,
      allowScripts: true,
      autoResize: true,
      debugMode: false, // Enable debug mode for Unity development
      zIndex: 999999, // Ensure above Unity canvas
      enablePointerEvents: true
    });

    // Set up event forwarding - send messages to Unity C#
    this.webViewManager.addEventListener('message', (msg: any) => {
      console.log('[Unity BalancyWebView] Received message from iframe:', msg);

      // Message is now raw string (no wrapper)
      const messageString = typeof msg === 'string' ? msg : JSON.stringify(msg);

      // Check if this is a BalancyIsReady message (action: 201)
      try {
        const parsed = typeof msg === 'string' ? JSON.parse(msg) : msg;
        if (parsed?.viewId && ((parsed?.type === 'viewCleared' && parsed.viewId === this.closingViewId) || (parsed?.type === 'viewLoadError' && parsed.viewId === this.activeViewId)) && Array.isArray(parsed.resourceUrls)) {
          this.webViewManager.retainResourceUrls(parsed.resourceUrls.filter((url: unknown) => typeof url === 'string'));
          this.closingViewId = this.activeViewId = null;
        }
        if (parsed && parsed.action === 201 && !this._shellId) {
          console.log('[Unity BalancyWebView] BalancyIsReady received - showing WebView');

          // Show the WebView
          this.show();

          // Notify Unity of successful load
          const sendToUnity = (window as any).sendToUnity;
          if (typeof sendToUnity === 'function') {
            try {
              sendToUnity('BalancyView', 'OnWebGLLoadCompleted', 'true');
              console.log('[Unity BalancyWebView] Unity notified of successful load');
            } catch (e) {
              console.error('[Unity BalancyWebView] Failed to notify Unity of load:', e);
            }
          }
        }
      } catch (e) {
        // Not JSON or error parsing, ignore
        console.log('[Unity BalancyWebView] Message is not JSON or error parsing:', e);
      }

      // Forward to Unity via global sendToUnity function (registered by jslib)
      try {
        const sendToUnity = (window as any).sendToUnity;

        if (typeof sendToUnity === 'function') {
          const success = sendToUnity('BalancyView', 'OnWebGLMessageReceived', messageString);

          if (success) {
            console.log('[Unity BalancyWebView] Message forwarded to Unity C# via sendToUnity');
          } else {
            console.error('[Unity BalancyWebView] Failed to forward message via sendToUnity');
          }
        } else {
          console.warn('[Unity BalancyWebView] sendToUnity function not available, queuing message');

          // Queue message for later delivery when Unity is ready
          if (!(window as any).__balancyMessageQueue) {
            (window as any).__balancyMessageQueue = [];
          }
          (window as any).__balancyMessageQueue.push({
            target: 'BalancyView',
            method: 'OnWebGLMessageReceived',
            message: messageString
          });
        }
      } catch (e) {
        console.error('[Unity BalancyWebView] Failed to forward message to Unity:', e);
      }

      // Also emit for any TypeScript listeners
      this.emit('message', msg);
    });

    this.webViewManager.addEventListener('load', (url: string) => {
      console.log('[Unity BalancyWebView] WebView loaded:', url);
      // Inject bridge scripts after load (exactly like BalancyWebView)
      this.onLoadCompletedReceived(true);
      this.emit('load', true);
    });

    this.webViewManager.addEventListener('close', () => {
      if (this.suppressUnityClose) return;
      console.log('[Unity BalancyWebView] WebView close event - notifying Unity and emitting "closed"');

      // Directly notify Unity C# that webview closed (for emergency exit)
      try {
        const sendToUnity = (window as any).sendToUnity;
        if (typeof sendToUnity === 'function') {
          sendToUnity('BalancyView', 'OnWebGLClosed', '');
          console.log('[Unity BalancyWebView] Unity notified of close via sendToUnity');
        } else {
          console.warn('[Unity BalancyWebView] sendToUnity not available, trying SendMessage');
          // Fallback to global SendMessage if available
          if (typeof (window as any).SendMessage === 'function') {
            (window as any).SendMessage('BalancyView', 'OnWebGLClosed', '');
            console.log('[Unity BalancyWebView] Unity notified of close via SendMessage');
          }
        }
      } catch (e) {
        console.error('[Unity BalancyWebView] Failed to notify Unity of close:', e);
      }

      // Also emit for any registered listeners
      this.emit('closed');
      console.log('[Unity BalancyWebView] "closed" event emitted, listeners:', this.eventHandlers.get('closed')?.length || 0);
    });

    // Set up periodic check for Unity SendMessage availability
    this.setupUnityMessageQueue();
  }

  /**
   * Set up periodic check to flush message queue when Unity becomes available
   */
  private setupUnityMessageQueue(): void {
    let checkCount = 0;
    const maxChecks = 100; // Check for 10 seconds (100ms * 100)

    const checkInterval = setInterval(() => {
      checkCount++;

      // Check if sendToUnity function is available
      const sendToUnity = (window as any).sendToUnity;
      const hasSendToUnity = typeof sendToUnity === 'function';

      // Check if we have queued messages
      const hasQueue = (window as any).__balancyMessageQueue && (window as any).__balancyMessageQueue.length > 0;

      if (hasSendToUnity && hasQueue) {
        console.log('[Unity BalancyWebView] sendToUnity now available, flushing queue');
        const queue = (window as any).__balancyMessageQueue;
        (window as any).__balancyMessageQueue = [];

        // Send all queued messages
        queue.forEach((msg: any) => {
          try {
            const success = sendToUnity(msg.target, msg.method, msg.message);
            if (success) {
              console.log('[Unity BalancyWebView] Queued message delivered to', msg.target);
            }
          } catch (e) {
            console.error('[Unity BalancyWebView] Failed to deliver queued message:', e);
          }
        });

        // Stop checking after successful delivery
        clearInterval(checkInterval);
        console.log('[Unity BalancyWebView] Message queue flushed successfully');
      } else if (checkCount >= maxChecks) {
        // Timeout after 10 seconds
        clearInterval(checkInterval);
        if (hasQueue) {
          console.warn('[Unity BalancyWebView] sendToUnity never became available after 10 seconds');
          console.warn('[Unity BalancyWebView] Queued messages:', (window as any).__balancyMessageQueue.length);
        }
      }
    }, 100); // Check every 100ms
  }

  /**
   * Open WebView with URL and owner data
   * @param url - URL to load
   * @param ownerJson - Owner JSON data (from Unity)
   * @param options - Additional options
   */
  openWebView(url: string, ownerJson: string, options?: { width?: number; height?: number; additionalInfo?: string }): void {
    console.log('[Unity BalancyWebView] Opening WebView:', url);

    // Store owner data for later injection
    this._shellId = null;
    this._ownerJson = ownerJson;
    this._additionalInfo = options?.additionalInfo || '{}';

    // WebViewManager.open() takes only URL
    this.webViewManager.open(url);
  }

  /**
   * Open WebView with HTML content and owner data
   * @param htmlContent - HTML content to display
   * @param ownerJson - Owner JSON data (from Unity)
   * @param options - Additional options
   */
  openWithHtml(htmlContent: string, ownerJson: string, options?: { additionalInfo?: string; manifestData?: any }): void {
    console.log('[Unity BalancyWebView] Opening WebView with HTML content:', htmlContent.length, 'bytes');

    // Store owner data for injection after load
    this._shellId = null;
    this._ownerJson = ownerJson;
    this._additionalInfo = options?.additionalInfo || '';
    this._manifestContent = options?.manifestData || null;

    // Use openHtml method from WebViewManager
    // autoShow=false because we'll show it manually when BalancyIsReady is received
    this.webViewManager.openHtml(htmlContent, {
      useSrcDoc: true,
      autoShow: false
    });
  }

  /**
   * Close the WebView
   */
  prepareWebView(shellId: string): void {
    this._shellId = shellId;
    this._ownerJson = ''; this._additionalInfo = '';
    this.webViewManager.openHtml('<!doctype html><html data-balancy-shell><head><meta name="viewport" content="width=device-width,initial-scale=1"><style>html,body,#root-container{margin:0;width:100%;height:100%;overflow:hidden;background:transparent}</style></head><body><div id="root-container"></div></body></html>',
      { useSrcDoc: true, autoShow: false }).catch(error => this.reportShellError(error));
  }

  hide(): void { this.webViewManager.hide(); }

  private reportShellError(error: unknown): void {
    (window as any).sendToUnity?.('BalancyView', 'OnWebGLMessageReceived',
      JSON.stringify({ type: 'shellError', shellId: this._shellId, error: String(error) }));
  }

  private suppressUnityClose = false;

  closeWebView(notifyUnity = true): void {
    this._shellId = null;
    console.log('[Unity BalancyWebView] Closing WebView');
    this.suppressUnityClose = !notifyUnity;
    try { this.webViewManager.close(); } finally { this.suppressUnityClose = false; }
  }

  /**
   * Send message to WebView
   * @param message - Message to send
   */
  sendMessage(message: string): void {
    try {
      const parsed = JSON.parse(message);
      if (parsed.type === 'loadView') this.activeViewId = parsed.viewId;
      if (parsed.type === 'clearView') this.closingViewId = parsed.viewId;
      if (parsed.type === 'invalidateCache' && parsed.scope !== 'localization') this.webViewManager.invalidateResourceUrls();
    } catch (_) { /* application payload */ }
    this.webViewManager.sendMessage(message).catch(error => console.error('[BalancyWebView] Send failed', error));
  }

  /**
   * Inject JavaScript code into the WebView
   * @param code - JavaScript code to inject
   */
  async injectCode(code: string): Promise<void> {
    await this.webViewManager.injectCode(code);
  }

  /**
   * Set WebView position
   * @param x - X position in pixels
   * @param y - Y position in pixels
   * @param width - Width in pixels
   * @param height - Height in pixels
   */
  setPosition(x: number, y: number, width: number, height: number): void {
    // WebViewManager handles this internally
    console.log('[Unity BalancyWebView] Set position:', { x, y, width, height });
  }

  /**
   * Set transparent background
   * @param transparent - Enable transparency
   */
  setTransparent(transparent: boolean): void {
    console.log('[Unity BalancyWebView] Set transparent:', transparent);
    // This is set during initialization, could be made dynamic if needed
  }

  /**
   * Set game UI mode
   * @param enabled - Enable game UI mode
   */
  setGameUIMode(enabled: boolean): void {
    console.log('[Unity BalancyWebView] Set game UI mode:', enabled);
    // This could adjust styling or behavior for game UI
  }

  /**
   * Show the WebView (called when BalancyIsReady)
   */
  show(): void {
    console.log('[Unity BalancyWebView] Showing WebView');
    this.webViewManager.show();
  }

  /**
   * Check if WebView is currently open
   */
  isOpen(): boolean {
    return this.webViewManager.isOpen();
  }

  /**
   * Configure the WebView
   * @param config - Configuration options
   */
  configure(config: Partial<WebViewOptions>): void {
    // Apply configuration to WebViewManager
    console.log('[Unity BalancyWebView] Configure:', config);
  }

  /**
   * Register event handler
   * @param event - Event name ('message', 'load', 'closed')
   * @param handler - Event handler function
   */
  on(event: string, handler: Function): void {
    if (!this.eventHandlers.has(event)) {
      this.eventHandlers.set(event, []);
    }
    this.eventHandlers.get(event)!.push(handler);
  }

  /**
   * Emit event to registered handlers
   * @param event - Event name
   * @param args - Event arguments
   */
  private emit(event: string, ...args: any[]): void {
    const handlers = this.eventHandlers.get(event);
    if (handlers) {
      handlers.forEach(handler => {
        try {
          handler(...args);
        } catch (error) {
          console.error(`[Unity BalancyWebView] Error in ${event} handler:`, error);
        }
      });
    }
  }

  /**
   * Handle load completed event (EXACTLY like BalancyWebView)
   * Injects bridge and owner data into the iframe
   */
  private onLoadCompletedReceived(success: boolean): void {
    if (success) {
      console.log('[Unity BalancyWebView] Load completed, injecting bridge');

      // Build owner info injection code
      const ownerInfo = `window.balancyViewOwner = JSON.parse(${JSON.stringify(this._ownerJson || 'null')});
        window.balancySettings = JSON.parse(${JSON.stringify(this._additionalInfo || 'null')});
        window.balancyShellId = ${JSON.stringify(this._shellId)};`;

      // Concatenate: Bridge + Scripts + Init
      const fullCode = `
        // #1 Owner Info
        ${ownerInfo}

        // #2 Bridge
        ${bridgeCode}

        // #3 Scripts (if any)
        window.balancy._installScripts(${JSON.stringify(this._scriptsCode)});

        // #4 Initialize
        window.balancy.initResponseHandler();
        console.log('Balancy fully initialized in iframe!');
        // Return explicit value to avoid iOS error code 5
        true;
      `;

      this.webViewManager.injectCode(fullCode, { sanitize: false }).catch((error) => {
        console.error('[Unity BalancyWebView] Main Injection Failed:', error);
        this.reportShellError(error);
      }).then(() => {
        console.log("[Unity BalancyWebView] Main Injection Completed");
      });
    }
  }

  /**
   * Set scripts code to be injected into the WebView
   */
  setScriptsCode(scriptsCode: string): void {
    this._scriptsCode = scriptsCode;
  }
}

// Export the class and create global instance for Unity
export { UnityBalancyWebView as BalancyWebView };

// Auto-initialize global instance for Unity WebGL
if (typeof window !== 'undefined') {
  (window as any).balancyWebView = UnityBalancyWebView.getInstance();
  console.log('[Unity BalancyWebView] Global instance created at window.balancyWebView');
}
